-- Project Schedule (P6 activities) -- SWR EPC-LV3_STC-20
-- run once in Supabase SQL editor (idempotent - safe to re-run)

create table if not exists project_schedule_activities (
  task_code text primary key,
  status_code text not null,       -- Not Started / In Progress / Completed
  wbs_id text,                     -- WBS hierarchy code e.g. SWR EPC-LV3_STC-20.4.10.10
  discipline text,                 -- CON / PRO / ENG / MIL / PAC / ASB (first segment of task_code)
  discipline_label text,           -- Construction / Procurement / Engineering / Milestone / Package Award / As-Built
  package text,                    -- PKG1 / PKG2 / PKG3
  area text,                       -- area/system code e.g. COM, WSB, WHA, WHB, MPB, TLB, GHB, ROD, EXT, FEN, DRA, SPL, SPLB
  task_name text not null,
  start_date date,
  end_date date,
  is_milestone boolean not null default false,
  sort_order int,
  updated_at timestamptz not null default now()
);

create index if not exists idx_psa_package on project_schedule_activities(package);
create index if not exists idx_psa_discipline on project_schedule_activities(discipline);
create index if not exists idx_psa_area on project_schedule_activities(area);
create index if not exists idx_psa_status on project_schedule_activities(status_code);

-- import data from SWR_EPCLV3_STC20Activities.xlsx (upsert by task_code, re-import safe)

on conflict (task_code) do update set
  status_code = excluded.status_code,
  wbs_id = excluded.wbs_id,
  discipline = excluded.discipline,
  discipline_label = excluded.discipline_label,
  package = excluded.package,
  area = excluded.area,
  task_name = excluded.task_name,
  start_date = excluded.start_date,
  end_date = excluded.end_date,
  is_milestone = excluded.is_milestone,
  sort_order = excluded.sort_order;
